                Some(edge) => {
                    if path.contains(&edge.to) {
                        break;
                    }
                    path.push(edge.to.clone());
                    current = edge.to.clone();
                }
                None => break,
            }
        }
        Echo {
            terminal: current,
            path,
        }
    }
}
