#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TransferTrace {
    pub from_thread: usize,
    pub to_thread: usize,
    pub at: String,
    pub payload: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fabric {
    threads: Vec<Vec<String>>,
    next_thread_id: usize,
}

impl Fabric {
    pub fn new() -> Self {
        Fabric {
            threads: Vec::new(),
            next_thread_id: 1,
        }
    }

    pub fn flow(&mut self, route: &[&str]) -> usize {
        let thread_id = self.next_thread_id;
        self.next_thread_id += 1;
        let route_vec: Vec<String> = route.iter().map(|s| s.to_string()).collect();
        self.threads.push(route_vec);
        thread_id
    }

    pub fn intersections(&self) -> Vec<String> {
        let mut node_count: HashMap<String, usize> = HashMap::new();
        for thread in &self.threads {
            let unique_nodes: HashSet<&String> = thread.iter().collect();
            for node in unique_nodes {
                *node_count.entry(node.clone()).or_insert(0) += 1;
            }
        }

        let mut intersections: Vec<String> = node_count
            .into_iter()
            .filter(|(_, count)| *count >= 2)
            .map(|(node, _)| node)
            .collect();

        intersections.sort();
        intersections
    }

    pub fn transfer(&self, from_thread: usize, to_thread: usize, payload: &str) -> Option<TransferTrace> {
        let from_route = self.threads.get(from_thread - 1)?;
        let to_route = self.threads.get(to_thread - 1)?;

        // Find first shared node in the order of from_route
        let from_nodes: HashSet<&String> = from_route.iter().collect();
        for node in from_route {
            if to_route.contains(node) && from_nodes.contains(node) {
                return Some(TransferTrace {
                    from_thread,
                    to_thread,
                    at: node.clone(),
                    payload: payload.to_string(),
                });
            }
        }

        None
    }
}
