use std::collections::{HashMap, HashSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Plan {
    pub task_id: String,
    pub node: String,
    pub promoted: bool,
    pub signals: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Node {
    pub name: String,
    pub cost: u32,
    pub capacity: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Ramp {
    pub from: String,
    pub to: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Signal {
    pub kind: String,
    pub node: String,
}

pub struct Scheduler {
    nodes: HashMap<String, Node>,
    ramps: Vec<Ramp>,
}

impl Scheduler {
    pub fn new() -> Self {
        Scheduler {
            nodes: HashMap::new(),
            ramps: Vec::new(),
        }
    }

    pub fn add_node(&mut self, name: &str, cost: u32, capacity: u32) {
        self.nodes.insert(
            name.to_string(),
            Node {
                name: name.to_string(),
                cost,
                capacity,
            },
        );
    }

    pub fn add_ramp(&mut self, from: &str, to: &str) {
        self.ramps.push(Ramp {
            from: from.to_string(),
            to: to.to_string(),
        });
    }

    pub fn schedule(
        &self,
        task_id: &str,
        candidates: &[&str],
        max_cost: u32,
    ) -> Option<Plan> {
        let mut skipped_full_node: Option<String> = None;
        let mut signals: Vec<String> = Vec::new();
        let mut promoted = false;

        for &candidate in candidates {
            let node = self.nodes.get(candidate)?;

            if node.cost > max_cost {
                continue;
            }

            if node.capacity == 0 {
                signals.push(format!("backpressure:{}", candidate));
                skipped_full_node = Some(candidate.to_string());
                continue;
            }

            // Check for promotion
            if let Some(skipped) = &skipped_full_node {
                for ramp in &self.ramps {
                    if ramp.from == *skipped && ramp.to == candidate {
                        promoted = true;
                        break;
                    }
                }
            }

            return Some(Plan {
                task_id: task_id.to_string(),
                node: candidate.to_string(),
                promoted,
                signals,
            });
        }

        None
    }
}
