use std::collections::{HashMap, VecDeque};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PreloadPlanner {
    nodes: HashMap<String, Vec<String>>,
}

impl PreloadPlanner {
    pub fn new() -> Self {
        PreloadPlanner {
            nodes: HashMap::new(),
        }
    }

    pub fn connect(&mut self, from: &str, to: &str) {
        self.nodes.entry(from.to_string()).or_default().push(to.to_string());
    }

    pub fn preload_from(&self, start_node: &str, depth: usize) -> Vec<String> {
        if depth == 0 {
            return vec![];
        }

        let mut visited = HashMap::new();
        let mut queue = VecDeque::new();
        let mut result = Vec::new();

        if !self.nodes.contains_key(start_node) {
            return result;
        }

        queue.push_back(start_node.to_string());
        visited.insert(start_node.to_string(), 0);

        while let Some(current_node) = queue.pop_front() {
            let current_depth = *visited.get(&current_node).unwrap();

            if current_depth < depth {
                if let Some(neighbors) = self.nodes.get(&current_node) {
                    for &neighbor in neighbors {
                        if !visited.contains_key(&neighbor) {
                            visited.insert(neighbor.clone(), current_depth + 1);
                            queue.push_back(neighbor.clone());
                        }
                    }
                }
            }

            // Only add to result if we're at the right depth
            if current_depth == depth {
                result.push(current_node);
            }
        }

        result.sort();
        result
    }
}
