use std::collections::{HashMap, HashSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RampTrace {
    pub path: Vec<String>,
    pub elevations: Vec<String>,
    pub promotions: usize,
    pub demotions: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RampRuntime {
    nodes: HashMap<String, String>,
    connections: HashMap<String, HashSet<String>>,
    elevations: HashMap<String, String>,
    promoted: usize,
    demoted: usize,
}

impl RampRuntime {
    pub fn new() -> Self {
        RampRuntime {
            nodes: HashMap::new(),
            connections: HashMap::new(),
            elevations: HashMap::new(),
            promoted: 0,
            demoted: 0,
        }
    }

    pub fn connect(&mut self, from: &str, to: &str) {
        self.nodes.insert(from.to_string(), "local".to_string());
        self.nodes.insert(to.to_string(), "local".to_string());

        self.connections
            .entry(from.to_string())
            .or_insert_with(HashSet::new)
            .insert(to.to_string());

        self.connections
            .entry(to.to_string())
            .or_insert_with(HashSet::new)
            .insert(from.to_string());
    }

    pub fn on_ramp(&mut self, from: &str, to: &str) {
        let from_elevation = self.elevations.get(from).cloned().unwrap_or("local".to_string());
        let to_elevation = if from_elevation == "local" {
            "parallel".to_string()
        } else {
            from_elevation.clone()
        };

        self.elevations.insert(to.to_string(), to_elevation.clone());

        if from_elevation == "local" && to_elevation == "parallel" {
            self.promoted += 1;
        }

        self.nodes.insert(from.to_string(), from_elevation);
        self.nodes.insert(to.to_string(), to_elevation.clone());
    }

    pub fn off_ramp(&mut self, from: &str, to: &str) {
        let from_elevation = self.elevations.get(from).cloned().unwrap_or("local".to_string());
        let to_elevation = "local".to_string();

        if from_elevation == "parallel" {
            self.demoted += 1;
        }

        self.elevations.insert(to.to_string(), to_elevation.clone());

        self.nodes.insert(from.to_string(), from_elevation);
        self.nodes.insert(to.to_string(), to_elevation);
    }

    pub fn trace(&self, from: &str) -> RampTrace {
        let mut path = Vec::new();
        let mut elevations = Vec::new();

        let mut current = from.to_string();
        let mut visited = HashSet::new();

        while !visited.contains(&current) && self.nodes.contains_key(&current) {
            visited.insert(current.clone());
            path.push(current.clone());

            let elevation = self.elevations.get(&current).cloned().unwrap_or("local".to_string());
            elevations.push(elevation.clone());

            if let Some(neighbors) = self.connections.get(&current) {
                for neighbor in neighbors {
                    if !visited.contains(neighbor) && self.nodes.contains_key(neighbor) {
                        current = neighbor.clone();
                        break;
                    }
                }
            } else {
                break;
            }
        }

        RampTrace {
            path,
            elevations,
            promotions: self.promoted,
            demotions: self.demoted,
        }
    }
}
