use std::collections::{HashMap, HashSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NodeRegistry {
    nodes: HashMap<String, Vec<String>>,
}

impl NodeRegistry {
    pub fn new() -> Self {
        NodeRegistry {
            nodes: HashMap::new(),
        }
    }

    pub fn register(&mut self, node_id: &str, capabilities: &[&str]) {
        let caps = capabilities.iter().map(|s| s.to_string()).collect();
        self.nodes.insert(node_id.to_string(), caps);
    }

    pub fn nodes_with(&self, capability: &str) -> Vec<String> {
        let mut result = Vec::new();
        for (node_id, caps) in &self.nodes {
            if caps.contains(&capability.to_string()) {
                result.push(node_id.clone());
            }
        }
        result.sort();
        result
    }
}
