use std::io::{self, BufRead};
use rust_ordo_ext::{AuditTimeline, AuditEvent};

fn main() {
    let mut timeline = AuditTimeline::new();
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        match parts[0] {
            "record" => {
                if parts.len() != 4 {
                    eprintln!("Usage: record THREAD KIND NODE");
                    std::process::exit(1);
                }
                let thread_id = parts[1].parse().unwrap();
                timeline.record(thread_id, parts[2], parts[3]);
            }
            "show" => {
                if parts.len() != 2 {
                    eprintln!("Usage: show THREAD");
                    std::process::exit(1);
                }
                let thread_id = parts[1].parse().unwrap();
                let events = timeline.events_for_thread(thread_id);
                if !events.is_empty() {
                    print!("audit=");
                    for (i, event) in events.iter().enumerate() {
                        if i > 0 {
                            print!(",");
                        }
                        print!("{}:{}@{}", event.index, event.kind, event.node);
                    }
                    println!();
                }
            }
            _ => {
                eprintln!("Unknown command: {}", parts[0]);
                std::process::exit(1);
            }
        }
    }
}
